package jp.personal.hanshinedge.validation;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;import org.junit.runner.RunWith;import org.json.*;import java.util.*;import jp.personal.hanshinedge.prediction.*;import jp.personal.hanshinedge.runtime.CapabilityGate;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class FrozenMf0EngineTest {
 @Test public void goldenTenCasesAndSums() throws Exception {
 String raw=new java.util.Scanner(InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("frozen-mf0-golden.json"),"UTF-8").useDelimiter("\\A").next();JSONObject all=new JSONObject(raw);JSONArray cases=all.getJSONArray("cases");assertEquals(10,cases.length());
 for(int c=0;c<cases.length();c++){JSONObject item=cases.getJSONObject(c),f=item.getJSONObject("f0");JSONArray runners=item.getJSONArray("runners");List<FrozenMf0Engine.Input> in=new ArrayList<>();for(int i=0;i<runners.length();i++){JSONObject r=runners.getJSONObject(i);int n=r.getInt("horseNo");in.add(new FrozenMf0Engine.Input(n,r.getString("name"),r.getDouble("odds"),f.getDouble(""+n)));}FrozenMf0Engine.Output actual=new FrozenMf0Engine().evaluate(in);JSONObject expected=item.getJSONObject("expected");assertEquals(expected.getString("action"),actual.action);assertEquals(expected.getString("reason"),actual.reason);double sf=0,sm=0,sb=0;for(int i=0;i<actual.rows.size();i++){FrozenMf0Engine.Row r=actual.rows.get(i);JSONObject e=expected.getJSONArray("rows").getJSONObject(i);assertEquals(e.getInt("horseNo"),r.horseNo);assertEquals(e.getDouble("m0"),r.m0,1e-12);assertEquals(e.getDouble("mf0"),r.mf0,1e-12);assertEquals(e.getDouble("edgePt"),r.edgePt,1e-12);assertEquals(e.getDouble("evQuote"),r.evQuote,1e-12);sf+=r.f0;sm+=r.m0;sb+=r.mf0;}assertEquals(1,sf,1e-12);assertEquals(1,sm,1e-12);assertEquals(1,sb,1e-12);}
 }
 @Test public void boundariesMissingHistoricalAndJump(){assertEquals("BUY",FrozenMf0Engine.threshold(1.15,3));assertEquals("PASS",FrozenMf0Engine.threshold(Math.nextDown(1.15),3));assertEquals("PASS",FrozenMf0Engine.threshold(1.15,Math.nextDown(3.0)));PredictionProvider p=new PredictionProvider();List<FrozenMf0Engine.Input> in=Arrays.asList(new FrozenMf0Engine.Input(1,"TEST",2.0,null),new FrozenMf0Engine.Input(2,"TEST",5.0,1.0));CapabilityGate.RaceContext live=new CapabilityGate.RaceContext("TEST","HANSHIN",1,false,true,false,CapabilityGate.FROZEN_MODEL);assertEquals("F0_NOT_READY",p.predict(live,in,1000L,1000).reason);CapabilityGate.RaceContext historical=new CapabilityGate.RaceContext("TEST","HANSHIN",1,false,false,false,CapabilityGate.FROZEN_MODEL);assertEquals("NOT_PROSPECTIVE",p.predict(historical,in,1000L,1000).reason);CapabilityGate.RaceContext jump=new CapabilityGate.RaceContext("TEST","HANSHIN",1,true,true,false,CapabilityGate.FROZEN_MODEL);PredictionProvider.Prediction blocked=p.predict(jump,in,1000L,1000);assertEquals("OBSTACLE_MODEL_BLOCKED",blocked.reason);assertNull(blocked.model);assertEquals("BLOCKED",blocked.finalAction);}
}
